bp = Blueprint("coach", __name__)


def _ai_cooldown_response():
    """WS7: kullanıcı ardışık AI arızası nedeniyle soğumadaysa 429+Retry-After
    döndür, değilse None. Kota REZERVASYONUNDAN ÖNCE çağrılır — soğuyan kullanıcı
    boşuna hak harcamasın. Redis yoksa (lokal/test) her zaman None (no-op)."""
    remaining = ai_recovery.ai_cooldown_remaining(current_user.id)
    if remaining:
        resp = jsonify({"error": t("coach.cooldown"), "retry_after": remaining})
        resp.status_code = 429
        resp.headers["Retry-After"] = str(remaining)
        return resp
    return None


@bp.route("/chat", methods=["POST"])
@require_auth
@limiter.limit(AI_RATELIMIT, key_func=_user_or_ip_key)
@limiter.limit(BEDROCK_RATELIMIT, key_func=_user_or_ip_key)  # generate_coach_reply Sonnet'te: daha sıkı tavan
@ai_concurrency_gate  # A1: bloklayıcı AI çağrıları tüm thread'leri doldurmasın
def chat():
    data = request.get_json(silent=True) or {}

    required_fields = ["weight", "height", "age",
                       "gender", "goal", "fitness_level", "current_activity"]
    for field in required_fields:
        if not data.get(field):
            return jsonify({"reply": t("coach.field_missing", field=field)}), 400

    try:
        weight = float(data["weight"])
        height = float(data["height"])
        age    = int(data["age"])
    except (ValueError, TypeError):
        return jsonify({"reply": t("coach.numeric_required")}), 400

    name             = current_user.username  # formdan değil, oturumdan al
    gender           = data["gender"]
    goal             = data["goal"]
    level            = data["fitness_level"]
    current_activity = data["current_activity"]
    user_message     = data.get("message", "")

    # Kullanıcının önceki kaydını çek
    previous_session = UserSession.query.filter_by(user_id=current_user.id)\
        .order_by(UserSession.created_at.desc())\
        .first()

    # Önceki veriler ve geçen süre
    previous_weight  = None
    previous_date    = None
    days_passed      = None

    if previous_session:
        previous_weight = previous_session.weight
        previous_date   = previous_session.created_at
        # Istanbul gün sınırına göre (CLAUDE.md); ham UTC farkı gece-yarısı
        # yakınında bir gün kayardı (F1.2).
        days_passed     = (app_today() - app_date_of(previous_date)).days

    bmr             = calculate_bmr(weight, height, age, gender)
    tdee            = calculate_tdee(bmr, current_activity)
    target_calories = calculate_target(tdee, goal)
    training_plan   = generate_training_plan(goal, level)
    nutrition_plan  = generate_nutrition_plan(goal, target_calories)
    coach_reply     = generate_coach_reply(
                          name, age, gender, weight, height,
                          goal, level, current_activity,
                          bmr, tdee, target_calories,
                          training_plan, nutrition_plan,
                          user_message,
                          previous_weight, days_passed,
                          language=current_user.language
                      )
    
    new_session = UserSession(
        name=name, age=age, gender=gender,
        weight=weight, height=height,
        goal=goal, fitness_level=level,
        current_activity=current_activity,
        bmr=bmr, tdee=tdee,
        target_calories=target_calories,
        training_plan=training_plan,
        nutrition_plan=nutrition_plan,
        coach_reply=coach_reply,
        user_id=current_user.id
    )
    db.session.add(new_session)
    db.session.commit()

    # Karşılaştırma verisi frontend'e gönder
    comparison = None
    if previous_weight and days_passed is not None:
        diff = round(weight - previous_weight, 1)
        comparison = {
            "previous_weight" : previous_weight,
            "days_passed"     : days_passed,
            "weight_diff"     : diff
        }

    return jsonify({
        "bmr"            : round(bmr),
        "tdee"           : round(tdee),
        "target_calories": round(target_calories),
        "training_plan"  : training_plan,
        "nutrition_plan" : nutrition_plan,
        "coach_reply"    : coach_reply,
        "comparison"     : comparison
    })


@bp.route("/ask", methods=["POST"])
@require_auth
@limiter.limit(AI_RATELIMIT, key_func=_user_or_ip_key)
@limiter.limit(AI_BURST_RATELIMIT, key_func=_user_or_ip_key)  # WS7: kısa-pencere burst tavanı
@ai_concurrency_gate  # A1: bloklayıcı AI çağrıları tüm thread'leri doldurmasın
def ask_coach():
    data     = request.get_json(silent=True) or {}
    question = (data.get("question") or "").strip()
    # Widget her istekte kullanıcının gördüğü sohbeti gönderir → kaynak-doğru.
    # Liste değilse None bırak ki _run_coach_conversation eski session'a düşsün.
    client_history = data.get("history")
    if not isinstance(client_history, list):
        client_history = None

    # Girdi kapısı (H2 uzunluk sınırı dahil) artık hattın Güvenlik Katmanı'nda:
    # app/services/moderation.py (WS3). Davranış aynı: boş → ask_something,
    # aşırı uzun → question_too_long, ikisi de 400.
    err_key = validate_question(question)
    if err_key:
        return jsonify({"error": t(err_key)}), 400

    # WS7: sağlayıcı arıza soğuması — kotadan ÖNCE. Soğuyan kullanıcı hak harcamaz.
    cooling = _ai_cooldown_response()
    if cooling is not None:
        return cooling

    # M4: /ask en pahalı yoldur (Bedrock Sonnet + FatSecret + öğe-başı LLM makro
    # batch'leri). Plan üretimi gibi premium-duyarlı HAFTALIK kotaya tabi tut —
    # non-premium için sınır, premium sınırsız. Salt rate-limit (30/saat)
    # freemium niyetini karşılamıyor, sürekli pahalı çağrıya izin veriyordu.
    quota_enabled = current_app.config.get("AI_CHAT_QUOTA_ENABLED", True)
    if quota_enabled and not reserve_ai_quota(
            current_user, "chat", FREE_WEEKLY_AI_CHATS):
        return jsonify({"error": t("coach.chat_quota_reached"),
                        "premium_required": True}), 402

    # WS3: yanıt üretimi modüler hatta (ai_pipeline.generate_answer — bağlam +
    # WS1 kalıcı hafıza + sağlayıcı döngüsü + biçimlendirici). Kota rezervasyon/
    # iade kararı burada kalır: hat is_error_fallback bayrağını döndürür.
    lang = current_user.language
    user_id = current_user.id
    try:
        result = generate_answer(user_id, question, client_history,
                                 language=lang)
        # Sağlayıcı dostça bir hata metni döndürürse önceden ayrılan hakkı geri ver.
        if result["is_error_fallback"]:
            ai_recovery.record_ai_failure(user_id)  # WS7: ardışık-arıza sayacı
            if quota_enabled:
                db.session.rollback()
                try:
                    refund_ai_quota(current_user, "chat")
                except Exception:
                    db.session.rollback()
                    current_app.logger.exception("AI chat quota refund failed")
        else:
            ai_recovery.clear_ai_failures(user_id)  # başarı → sayaç sıfırla
        return jsonify({"answer": result["answer"],
                        "conversation_id": result["conversation_id"]})
    except Exception:
        current_app.logger.exception("Koç yanıtı üretilemedi")
        db.session.rollback()
        ai_recovery.record_ai_failure(user_id)
        if quota_enabled:
            try:
                refund_ai_quota(current_user, "chat")
            except Exception:
                db.session.rollback()
                current_app.logger.exception("AI chat quota refund failed")
        return jsonify({"error": t("coach.reply_failed")}), 500


def _sse(event, data):
    """Tek bir SSE çerçevesi. ensure_ascii=False: Türkçe karakterler \\uXXXX'e
    şişmesin (ilk-token gecikmesi ve bant genişliği)."""
    return f"event: {event}\ndata: {json.dumps(data, ensure_ascii=False)}\n\n"


def _refund_chat_quota(user_id, reserved_week=None):
    """Akış içinde kota iadesi: current_user yerine ID ile taze kullanıcı çek —
    generator view döndükten SONRA çalışır, proxy'ye güvenme."""
    try:
        user = db.session.get(User, user_id)
        if user is not None:
            refund_ai_quota(user, "chat", reserved_week=reserved_week)
    except Exception:
        db.session.rollback()
        current_app.logger.exception("AI chat quota refund failed (stream)")


@bp.route("/ask/stream", methods=["POST"])
@require_auth
@limiter.limit(AI_RATELIMIT, key_func=_user_or_ip_key)
@limiter.limit(AI_BURST_RATELIMIT, key_func=_user_or_ip_key)  # WS7: kısa-pencere burst tavanı
@ai_stream_concurrency_gate  # slotu YANIT KAPANANA dek tutar (bkz. ai_gate)
def ask_coach_stream():
    """/ask'in akışlı ikizi (WS2). Aynı kapılar, aynı hat; fark: yanıt token
    token gelir. /ask AYNEN durur (istemci akışı desteklemezse ona düşer).

    Çerçeveler: meta → delta* → done | error. Sağlayıcı istisnaları asla
    istemciye yazılmaz; error çerçevesi i18n'lenmiş dostça metin taşır.
    """
    data = request.get_json(silent=True) or {}
    question = (data.get("question") or "").strip()
    client_history = data.get("history")
    if not isinstance(client_history, list):
        client_history = None

    err_key = validate_question(question)
    if err_key:
        return jsonify({"error": t(err_key)}), 400

    # WS7: sağlayıcı arıza soğuması — kotadan ÖNCE (bloklayıcı /ask ile aynı kural).
    cooling = _ai_cooldown_response()
    if cooling is not None:
        return cooling

    quota_enabled = current_app.config.get("AI_CHAT_QUOTA_ENABLED", True)
    if quota_enabled and not reserve_ai_quota(
            current_user, "chat", FREE_WEEKLY_AI_CHATS):
        return jsonify({"error": t("coach.chat_quota_reached"),
                        "premium_required": True}), 402
    reserved_week = reservation_week(current_user, "chat") if quota_enabled else None

    # Generator view DÖNDÜKTEN sonra çalışır: request proxy'lerine (current_user)
    # değil, şimdi çözülmüş düz değerlere bağlan.
    user_id = current_user.id
    lang = current_user.language
    req_id = current_request_id()  # WS6: izleme kimliği — jeneratörden önce çöz

    def generate():
        work_performed = False
        try:
            for event in stream_answer(user_id, question, client_history,
                                       language=lang):
                kind = event["type"]
                if kind == "meta":
                    yield _sse("meta", {"conversation_id": event["conversation_id"],
                                        "request_id": req_id})
                elif kind == "delta":
                    yield _sse("delta", {"text": event["text"]})
                    work_performed = True
                elif kind == "error":
                    work_performed = (work_performed or
                                      bool(event.get("work_performed")))
                    if work_performed:
                        yield _sse("error", {"message": t(event["key"])})
                        return

                    ai_recovery.record_ai_failure(user_id)  # WS7: ardışık-arıza sayacı
                    if quota_enabled:
                        _refund_chat_quota(user_id, reserved_week)
                    yield _sse("error", {"message": t(event["key"])})
                    return
                elif kind == "done":
                    # Sağlayıcı dostça hata metni döndürdüyse hak iade edilir
                    # (bloklayıcı /ask ile birebir aynı kural).
                    if event["is_error_fallback"]:
                        ai_recovery.record_ai_failure(user_id)
                        if quota_enabled:
                            _refund_chat_quota(user_id, reserved_week)
                    else:
                        ai_recovery.clear_ai_failures(user_id)  # başarı → sayaç sıfırla
                    yield _sse("done", {"text": event["text"],
                                        "is_error_fallback": event["is_error_fallback"]})
                    return
        except GeneratorExit:
            # İstemci koptu; kısmi yanıt hat katmanında kaydedildi. Kota İADE
            # EDİLMEZ: model üretti, kullanıcı gördü — hak harcanmıştır.
            raise
        except Exception:
            current_app.logger.error("Coach stream failed unexpectedly")
            db.session.rollback()
            if work_performed:
                yield _sse("error", {"message": t("coach.reply_failed")})
                return

            ai_recovery.record_ai_failure(user_id)
            if quota_enabled:
                _refund_chat_quota(user_id, reserved_week)
            yield _sse("error", {"message": t("coach.reply_failed")})

    response = Response(stream_with_context(generate()),
                        mimetype="text/event-stream")
    # nginx `location /` altında proxy_buffering zaten kapalı; bu başlık ara
    # katmanlar (ve /health dışı proxy'ler) için açık güvenceyi ekler.
    response.headers["X-Accel-Buffering"] = "no"
    response.headers["Cache-Control"] = "no-cache"
    return response


@bp.route("/coach/history", methods=["GET"])
@require_auth
def coach_history():
    """Aktif konuşmanın son mesajları (eski→yeni) — WS1: hafıza tarayıcı
    yenilemesini böyle atlatır. Widget hidrasyonu PR 3'te (streaming) bağlanır.
    Sorgu memory_manager içinde current_user.id'ye scope'ludur."""
    conv, rows = memory_manager.recent_messages(current_user.id, limit=50)
    return jsonify({
        "conversation_id": conv.id if conv else None,
        "messages": [
            {"role": m.role, "text": m.content,
             "created_at": (m.created_at.isoformat() + "Z") if m.created_at else None}
            for m in rows
        ],
    })


@bp.route("/coach/conversation/reset", methods=["POST"])
@require_auth
def coach_conversation_reset():
    """Konuşma sıfırlama ucu (WS1): aktif konuşmayı ARŞİVLER — mesajlar
    silinmez, sonraki soru taze bir konuşma açar. CSRF: yazma metodu olduğu
    için hooks._csrf_protect kapsar; csrf.js fetch'e başlığı otomatik ekler."""
    archived = memory_manager.archive_active_conversation(current_user.id)
    return jsonify({"ok": True, "archived": archived})
